            if d <= q.radius + 5 and (not q.inner or d >= q.inner - 5) then return true end
        end
    end
    return false
end
function F.bossMove(boss, c, low)
    local r = M.root()
    if not r then return end
    local floor = (D.Boss and D.Boss.FLOOR_RADIUS or 100) - 5
    local minD, maxD = low and 80 or 62, low and 110 or 78
    local dn = (r.Position - boss) * Vector3.new(1, 0, 1)
    local rc = (r.Position - c) * Vector3.new(1, 0, 1)
    if dn.Magnitude >= minD and dn.Magnitude <= maxD and rc.Magnitude <= floor and not F.inZone(r.Position.X, r.Position.Z) then return end
    local spot, bs
    for _, keep in ipairs(low and { 90, 100 } or { 74, 68, 77, 64 }) do
        for i = 0, 23 do
            local ang = i * math.pi / 12
            local p = boss + Vector3.new(math.cos(ang), 0, math.sin(ang)) * keep
            if ((p - c) * Vector3.new(1, 0, 1)).Magnitude <= floor then
                local score = -((p - r.Position) * Vector3.new(1, 0, 1)).Magnitude * 0.05 - math.abs(keep - 72) * 0.2
                if F.inZone(p.X, p.Z) then score = score - 1000 end
                if not bs or score > bs then spot, bs = p, score end
            end
        end
    end
    if spot then M.tp(Vector3.new(spot.X, c.Y + 4, spot.Z)) end
end
F.on("Boss", function(a)
