function E.hasAura(a, owned)
    if D.auraOut[a.id] == false then return false end
    if a.pass then return A("Pass_" .. a.pass) == true end
    if a.skip and A("Pass_" .. a.skip) == true then return true end
    if a.exclusive then return owned[a.id] == true end
    return num("TotalWins") >= (a.trophies or math.huge)
end
function E.equipBestAura()
    local raw = json("OwnedAuras")
    local owned = {}
    for k, v in pairs(raw) do if type(k) == "string" then owned[k] = true elseif type(v) == "string" then owned[v] = true end end
    local w, best, bm = M.world(), nil, nil
    for _, a in ipairs(D.Auras and D.Auras.list or {}) do
        if not a.better and E.hasAura(a, owned) then
            local m = a.mults and (a.mults[w] or a.mults[#a.mults]) or a.mult or 0
            if not bm or m > bm then best, bm = a, m end
        end
    end
    local base = bm or 1
    for _, a in ipairs(D.Auras and D.Auras.list or {}) do
        if a.better and E.hasAura(a, owned) then
            local m = base * (1 + a.better)
            if not bm or m > bm then best, bm = a, m end
        end
    end
    if best and A("Aura") ~= best.id then
        local ok = invokeR("EquipAura", best.id)
        if ok then say(__T["Aura "] .. tostring(best.name)) end
    end
    E.auraTxt = best and ("Aura: " .. tostring(best.name) .. __T[" x"] .. tostring(bm)) or "No aura unlocked yet"
end
function E.lockedSet()
    local set = {}
    for k, v in pairs(json("LockedPets")) do
        if type(k) == "string" and v then set[k] = true elseif v ~= nil then set[tostring(v)] = true end
    end
    return set
end
function E.weakPets()
    local defs = {}
    for _, p in ipairs(D.Pets and D.Pets.list or {}) do defs[p.id] = p end
    local pets, eq, tiers, locked, w = json("Pets"), json("Equipped"), json("PetTiers"), E.lockedSet(), M.world()
    local function value(d, uid)
        local m = d.mults and (d.mults[w] or d.mults[#d.mults]) or d.mult or 0
        local t = tiers[uid] or 0
        local ok, f = true, 1
        if t ~= 0 and D.FuseC and D.FuseC.factor then ok, f = pcall(D.FuseC.factor, t) end
        return m * (ok and f or 1)
    end
    local eqSet, eqMin, n = {}, math.huge, 0
    for _, uid in pairs(eq) do
        uid = tostring(uid)
        eqSet[uid] = true
        n += 1
        local d = defs[pets[uid]]
        eqMin = math.min(eqMin, d and value(d, uid) or 0)
    end
    local out = {}
    if n < num("EquipMax") or eqMin == math.huge then return out end
    local allow = val("pe_delr", nil)
    for uid, id in pairs(pets) do
        uid = tostring(uid)
        local d = defs[id]
        local fusable = on("pe_fuse") and D.FuseC and D.FuseC.fusable and select(2, pcall(D.FuseC.fusable, id)) == true
        if d and not eqSet[uid] and not locked[uid] and not d.mults and not d.pass and (tiers[uid] or 0) == 0 and not fusable and value(d, uid) < eqMin and (type(allow) ~= "table" or allow[d.rarity]) then out[#out + 1] = uid end
    end
    return out
end
function E.fuse()
    if not on("pe_fuse") or not (D.FuseL and D.FuseL.groups) or not M.alive() then return end
    if os.clock() - (E.fuseAt or -1e9) < 8 then return end
    E.fuseAt = os.clock()
    local pets, locked, eqSet, free = json("Pets"), E.lockedSet(), {}, {}
    for _, uid in pairs(json("Equipped")) do eqSet[tostring(uid)] = true end
    for uid, id in pairs(pets) do if not eqSet[tostring(uid)] and not locked[tostring(uid)] then free[uid] = id end end
    local ok, groups = pcall(D.FuseL.groups, free, json("PetTiers"), {}, {})
    if not ok or type(groups) ~= "table" or #groups == 0 then return end
    S.task = __T["Fusing pets"]
    M.tp(M.origin() + Vector3.new(30, 4, 26))
    task.wait(0.25)
    for i = 1, math.min(#groups, 3) do
        local good, msg = invokeR("Fuse", "fuse", groups[i].uids)
        LOG("fuse", groups[i].kind, groups[i].tier, good, typeof(msg) == "string" and msg or "")
        if good then S.fused = (S.fused or 0) + 1 else E.hatchMsg = typeof(msg) == "string" and msg or nil break end
        task.wait(0.3)
    end
end
