function E.hatch(force)
    local want = val("pe_egg", "Best I Can Afford")
    local list = E.eggList()
    local wins = num("Wins") - val("pe_keep", 0)
    local egg
    if want == "Best I Can Afford" then
        for _, eg in ipairs(list) do if wins >= eg.cost then egg = eg end end
    else
        for _, eg in ipairs(list) do if eg.name == want then egg = eg end end
    end
    if not egg or wins < egg.cost then return end
    local n = wins >= egg.cost * 3 and 3 or 1
    if not force and (A("InStages") or F.busy or on("st_on")) then return end
    local w = M.home()
    local stand = D.Pets and D.Pets.STANDS and D.Pets.STANDS[w] or {}
    local idx = table.find(stand, egg.id)
    local ep = idx and D.World and D.World.EGGS and D.World.EGGS[idx]
    local r = M.root()
    if not (ep and r) then return end
    local back = r.CFrame
    local spot = M.origin(w) + ep + Vector3.new(0, 3, 4)
    M.tp(spot)
    task.wait(0.3)
    local ok, msg = invokeR("PetAction", "hatch", { egg = egg.id, count = n })
    if not ok then
        M.tp(spot)
        task.wait(0.6)
        ok, msg = invokeR("PetAction", "hatch", { egg = egg.id, count = n })
    end
    if not on("tr_on") and not on("st_on") then pcall(function() M.root().CFrame = back end) end
    LOG("hatch", egg.id, n, ok, msg)
    if ok then S.hatched += n E.hatchMsg = nil else E.hatchMsg = tostring(msg or "") end
    return ok
end
